import std.io
import std.fs

pub fn main() effect io -> Result<(), fs.FsError> {
    match fs.makeDir("rt") {
        Ok(_) => { io.println("mkdir-ok") }
        Err(_) => { io.println("mkdir-bad") }
    }
    match fs.writeFile("rt/a.txt", "alpha") {
        Ok(_) => { io.println("write-ok") }
        Err(_) => { io.println("write-bad") }
    }
    match fs.readFile("rt/a.txt") {
        Ok(c) => {
            if c == "alpha" { io.println("read-ok") } else { io.println("read-bad") }
        }
        Err(_) => { io.println("read-bad") }
    }
    match fs.appendFile("rt/a.txt", "-beta") {
        Ok(_) => { io.println("append-ok") }
        Err(_) => { io.println("append-bad") }
    }
    match fs.readFile("rt/a.txt") {
        Ok(c) => {
            if c == "alpha-beta" { io.println("append-read-ok") } else { io.println("append-read-bad") }
        }
        Err(_) => { io.println("append-read-bad") }
    }
    match fs.listDir("rt") {
        Ok(xs) => {
            var n: Int64 = 0
            for _ in xs { n = n + 1 }
            if n == 1 { io.println("list-ok") } else { io.println("list-bad") }
        }
        Err(_) => { io.println("list-bad") }
    }
    match fs.removeFile("rt/a.txt") {
        Ok(_) => { io.println("rm-ok") }
        Err(_) => { io.println("rm-bad") }
    }
    match fs.removeDir("rt") {
        Ok(_) => { io.println("rmdir-ok") }
        Err(_) => { io.println("rmdir-bad") }
    }
    return Ok(())
}
